/*
 * One homework as the learner sees it, or the list of their homework (no stepId).
 * Learners never see a Step that is not shared (SCOPE), so the filter is here.
 * Numbers count the shared steps of each kind in plan order, as learnerHome does,
 * so "Homework 2" on Home is "Homework 2" here.
 */
(async () => {
  try {
    const me = String(Inputs.userId || '');
    if (!me) throw new Error('no session user');
    const q = (c, where) => Noodl.Records.query(c, where, { limit: 1000, plain: true });
    const users = await q('_User', { objectId: { equalTo: me } });
    Outputs.me = { timezone: (users[0] && users[0].timezone) || '' };

    const stepId = String(Inputs.stepId || '');
    let planId = null;
    if (stepId) {
      const found = await q('Step', { objectId: { equalTo: stepId } });
      const s = found[0];
      if (!s || s.learner !== me || s.shared !== true || s.kind !== 'homework') throw new Error('not a shared homework of the caller: ' + stepId);
      planId = s.plan;
    } else {
      const plans = await q('Plan', { learner: { equalTo: me } });
      const byStart = plans.slice().sort((a, b) => String(b.startedOn).localeCompare(String(a.startedOn)));
      const plan = plans.find((p) => p.status === 'active') || byStart[0] || null;
      planId = plan ? plan.objectId : null;
    }

    const rows = planId ? (await q('Step', { plan: { equalTo: planId } }))
      .filter((s) => s.learner === me && s.shared === true)
      .sort((a, b) => a.position - b.position) : [];
    const homework = rows.filter((s) => s.kind === 'homework');
    const subs = homework.length ? await q('Submission', { learner: { equalTo: me } }) : [];
    const versionsOf = (id) => subs.filter((x) => x.step === id).sort((a, b) => b.version - a.version);

    Outputs.list = homework.map((s, i) => ({
      id: s.objectId, n: i + 1, title: s.title || '', status: s.status, dueAt: s.dueAt || null,
      versions: versionsOf(s.objectId).length
    }));

    if (!stepId) {
      Outputs.step = null;
      Outputs.versions = [];
      Outputs.done();
      return;
    }
    const i = homework.findIndex((s) => s.objectId === stepId);
    const s = homework[i];
    Outputs.step = {
      id: s.objectId, n: i + 1, title: s.title || '', status: s.status, dueAt: s.dueAt || null,
      brief: s.brief || '',
      handInChecklist: Array.isArray(s.handInChecklist) ? s.handInChecklist : [],
      resources: Array.isArray(s.resources) ? s.resources : [],
      canHandIn: s.status !== 'approved'
    };
    const versions = versionsOf(stepId);
    Outputs.versions = versions.map((v, j) => ({
      id: v.objectId, version: v.version, kind: v.kind,
      files: Array.isArray(v.files) ? v.files.map((f) => ({ file: f.file, fileName: f.fileName })) : [],
      url: v.url || null, text: v.text || null,
      note: v.note || null, review: v.review || 'pending', reviewNote: v.reviewNote || null,
      reviewedAt: v.reviewedAt || null, handedInAt: v.createdAt, newest: j === 0
    }));
    Outputs.done();
  } catch (e) {
    console.error('[dbu:myHomework]', String((e && e.message) || e));
    Outputs.failed();
  }
})();
